    func testBuildAndRunBundlesCustomMacOSAppIcon() throws {
        let script = try readPackageFile("script/build_and_run.sh")
        let generator = try readPackageFile("script/generate_app_icon.sh")
        let artifactSizeGate = try readPackageFile("script/check_release_artifact_size.sh")
        let bundleMetadataVerifier = try readPackageFile("script/verify_bundle_metadata.sh")
        let packageSizePolicy = try readPackageFile("docs/release/package-size-policy.md")
        let masterURL = packageRoot().appendingPathComponent("packaging/Suisui-AppIcon-1024.png")
        let iconURL = packageRoot().appendingPathComponent("packaging/Suisui.icns")

        let imageSource = try XCTUnwrap(CGImageSourceCreateWithURL(masterURL as CFURL, nil))
        let properties = try XCTUnwrap(CGImageSourceCopyPropertiesAtIndex(imageSource, 0, nil) as? [CFString: Any])
        XCTAssertEqual(properties[kCGImagePropertyPixelWidth] as? Int, 1024)
        XCTAssertEqual(properties[kCGImagePropertyPixelHeight] as? Int, 1024)
        XCTAssertTrue(FileManager.default.fileExists(atPath: iconURL.path))
        let iconBytes = try XCTUnwrap(
            FileManager.default.attributesOfItem(atPath: iconURL.path)[.size] as? NSNumber
        ).intValue
        XCTAssertLessThanOrEqual(iconBytes, 1_300_000)
        XCTAssertTrue(generator.contains("icon_16x16.png"))
        XCTAssertTrue(generator.contains("icon_512x512@2x.png"))
        XCTAssertTrue(generator.contains("iconutil -c icns"))
        XCTAssertTrue(script.contains("APP_ICON_SOURCE=\"$ROOT_DIR/packaging/Suisui.icns\""))
        XCTAssertTrue(script.contains("SWIFT_PRODUCT_NAME=\"${SWIFT_PRODUCT_NAME:-$APP_NAME}\""))
        XCTAssertTrue(script.contains("--product \"$SWIFT_PRODUCT_NAME\""))
        XCTAssertTrue(script.contains("BUILD_BINARY=\"$BUILD_DIR/$SWIFT_PRODUCT_NAME\""))
        XCTAssertTrue(script.contains("RELEASE_BUILD_PURPOSE=\"${SUISUI_RELEASE_BUILD_PURPOSE:-distribution}\""))
        XCTAssertTrue(script.contains("release performance build purpose requires --build-only with release configuration"))
        XCTAssertTrue(script.contains("if [[ \"$RELEASE_BUILD_PURPOSE\" == \"distribution\" ]]"))
        XCTAssertTrue(script.contains("cp \"$APP_ICON_SOURCE\" \"$APP_RESOURCES/Suisui.icns\""))
        XCTAssertTrue(script.contains("<key>CFBundleIconFile</key>"))
        XCTAssertTrue(script.contains("<string>Suisui.icns</string>"))
        XCTAssertTrue(bundleMetadataVerifier.contains("CFBundleIconFile"))
        XCTAssertTrue(bundleMetadataVerifier.contains("missing bundled app icon"))
        XCTAssertTrue(bundleMetadataVerifier.contains("com.apple.security.device.audio-input"))
        XCTAssertTrue(bundleMetadataVerifier.contains("assert_eq \"$ENTITLEMENT_KEY_COUNT\" \"1\""))
        XCTAssertTrue(artifactSizeGate.contains("SUISUI_MAX_ZIP_ARTIFACT_BYTES:-8388608"))
        XCTAssertTrue(packageSizePolicy.contains("視覚上十分な512px相当に最適化"))
    }

    func testPerformanceReleaseBuildPurposeCannotBypassInteractiveOrDebugDistributionChecks() throws {
        let result = try runScript(
            "script/build_and_run.sh",
            arguments: ["--build-only"],
            environment: [
                "SUISUI_RELEASE_BUILD_PURPOSE": "performance",
                "SUISUI_BUILD_CONFIGURATION": "debug"
            ]
        )

        XCTAssertEqual(result.exitCode, 2, result.output)
        XCTAssertTrue(
            result.output.contains("release performance build purpose requires --build-only with release configuration"),
            result.output
        )
        XCTAssertFalse(result.output.contains("Building for debugging"), result.output)
    }

