    func testCIScriptSeparatesLightweightPRGateFromRuntimeAndVisualGates() throws {
        let script = try readPackageFile("scripts/ci.sh")
        let automatedPreflight = try readPackageFile("script/check_automated_release_preflight.sh")
        let phase = try readPackageFile("tasks/Phase14-QualityRegressionHardening.md")

        XCTAssertTrue(script.contains("CI_RUNTIME_GATES=\"${SUISUI_CI_RUNTIME_GATES:-0}\""))
        XCTAssertTrue(script.contains("CI_VISUAL_GATES=\"${SUISUI_CI_VISUAL_GATES:-0}\""))
        XCTAssertTrue(script.contains("CI_RELEASE_GATES=\"${SUISUI_CI_RELEASE_GATES:-0}\""))
        XCTAssertTrue(script.contains("CI_PERFORMANCE_GATES=\"${SUISUI_CI_PERFORMANCE_GATES:-0}\""))
        XCTAssertTrue(script.contains("CI_STRESS_GATES=\"${SUISUI_CI_STRESS_GATES:-0}\""))
        XCTAssertTrue(script.contains("run_pr_gate()"))
        XCTAssertTrue(script.contains("swift test --filter AppExperienceSourceTests"))
        XCTAssertTrue(script.contains("swift test --filter QualitySourceContractTests"))
        XCTAssertTrue(script.contains("script/check_pseudo_voiceover_paths.sh --swift-test"))
        XCTAssertTrue(script.contains("swift test --filter ProjectBoardStoreTests"))
        XCTAssertTrue(script.contains("run_performance_gates()"))
        XCTAssertTrue(script.contains("script/check_release_launch_performance_smoke.sh"))
        XCTAssertTrue(script.contains("SUISUI_PERFORMANCE_PROFILE=\"${SUISUI_PERFORMANCE_PROFILE:-release}\""))
        XCTAssertTrue(script.contains("SUISUI_PERFORMANCE_BUILD_CONFIGURATION=\"${SUISUI_PERFORMANCE_BUILD_CONFIGURATION:-release}\""))
        XCTAssertTrue(script.contains("run_stress_gates()"))
        XCTAssertTrue(script.contains("./script/check_performance_stress_suite.sh"))
        XCTAssertTrue(script.contains("run_runtime_gates()"))
        XCTAssertTrue(script.contains("script/check_runtime_accessible_crud_smoke.sh"))
        XCTAssertTrue(script.contains("script/check_layout_stability_smoke.sh"))
        XCTAssertTrue(script.contains("run_visual_gates()"))
        XCTAssertTrue(script.contains("script/check_ci_visual_gate.sh"))
        XCTAssertTrue(script.contains("if [[ \"$CI_PERFORMANCE_GATES\" == \"1\" ]]; then"))
        XCTAssertTrue(script.contains("if [[ \"$CI_STRESS_GATES\" == \"1\" ]]; then\n    run_stress_gates"))
        XCTAssertTrue(script.contains("if [[ \"$CI_RUNTIME_GATES\" == \"1\" ]]; then"))
        XCTAssertTrue(script.contains("if [[ \"$CI_VISUAL_GATES\" == \"1\" ]]; then"))
        XCTAssertLessThan(
            try XCTUnwrap(script.range(of: "run_pr_gate")).lowerBound,
            try XCTUnwrap(script.range(of: "run_runtime_gates")).lowerBound
        )

        XCTAssertTrue(automatedPreflight.contains("SUISUI_CI_RELEASE_GATES=1 ./scripts/ci.sh"))
        XCTAssertTrue(automatedPreflight.contains("./scripts/ci.sh ui-runtime"))
        XCTAssertTrue(automatedPreflight.contains("./scripts/ci.sh ui-visual"))
        XCTAssertTrue(automatedPreflight.contains("./scripts/ci.sh ui-performance"))
        XCTAssertTrue(phase.contains("- [x] `scripts/ci.sh` が軽量PR gateと重いruntime gateを混同しないことをsource testで固定する。"))
        XCTAssertTrue(phase.contains("- [x] `scripts/ci.sh` はunit/sourceを必須、runtime/visualは明示フラグで実行する。"))
    }

