    func testVisualBaselineManifestCoversProductScreensThemesAndSemanticTolerances() throws {
        let manifestData = try Data(contentsOf: packageRoot().appendingPathComponent("docs/quality/visual-baseline-manifest.json"))
        let manifest = try XCTUnwrap(
            JSONSerialization.jsonObject(with: manifestData) as? [String: Any],
            "Visual baseline manifest must be parseable JSON so release scripts can consume it without ad hoc text parsing."
        )
        let artifactRoot = try XCTUnwrap(manifest["artifactRoot"] as? String)
        let screens = try XCTUnwrap(manifest["screens"] as? [[String: Any]])
        let tolerances = try XCTUnwrap(manifest["semanticTolerances"] as? [String: Any])

        XCTAssertEqual((manifest["schemaVersion"] as? NSNumber)?.intValue, 2)
        XCTAssertEqual(artifactRoot, "docs/release/evidence/ui-screenshots")
        let screenIDs = Set(screens.compactMap { $0["id"] as? String })
        let coreSystemScreens: Set<String> = [
            "project-board",
            "inbox",
            "today",
            "settings-overview",
            "settings-appearance",
            "mcp-settings",
            "voice-command"
        ]
        let sampleDerivedScreens: Set<String> = [
            "inbox-voice",
            "projects-overview",
            "schedule",
            "schedule-workload",
            "done",
            "settings-integrations",
            "assistant-queue-waiting-review",
            "assistant-queue-approved",
            "assistant-queue-failed"
        ]
        XCTAssertEqual(screenIDs, coreSystemScreens.union(sampleDerivedScreens))
        let expectedViewports: [String: (width: Int, height: Int)] = [
            "project-board": (1_024, 676),
            "inbox": (1_024, 676),
            "today": (1_024, 676),
            "inbox-voice": (1_024, 676),
            "projects-overview": (1_024, 676),
            "schedule": (1_024, 676),
            "schedule-workload": (1_024, 676),
            "done": (1_024, 676),
            "assistant-queue-waiting-review": (1_024, 676),
            "assistant-queue-approved": (1_024, 676),
            "assistant-queue-failed": (1_024, 676),
            "settings-overview": (720, 676),
            "settings-integrations": (720, 676),
            "settings-appearance": (720, 676),
            "mcp-settings": (720, 676),
            "voice-command": (760, 640)
        ]
        let expectedAXTargets: [String: String] = [
            "project-board": "project-board-detail",
            "inbox": "inbox-workflow",
            "today": "today-workflow",
            "inbox-voice": "inbox-voice-intake-detail",
            "projects-overview": "projects-portfolio-overview",
            "schedule": "schedule-mini-calendar",
            "schedule-workload": "schedule-workload-attention-banner",
            "done": "done-workflow",
            "assistant-queue-waiting-review": "assistant-queue-row-visual-waiting",
            "assistant-queue-approved": "assistant-queue-row-visual-approved",
            "assistant-queue-failed": "assistant-queue-row-visual-failed",
            "settings-overview": "settings-status-overview",
            "settings-integrations": "settings-google-calendar-id-save-flow",
            "settings-appearance": "settings-theme-picker",
            "mcp-settings": "mcp-paid-execution-boundary-row",
            "voice-command": "voice-command-root"
        ]

        for screen in screens {
            let screenID = try XCTUnwrap(screen["id"] as? String)
            let themes = try XCTUnwrap(screen["themes"] as? [String], "missing themes for \(screenID)")
            let artifacts = try XCTUnwrap(screen["artifacts"] as? [String: String], "missing artifacts for \(screenID)")
            let viewport = try XCTUnwrap(screen["viewport"] as? [String: Any], "missing viewport for \(screenID)")

            XCTAssertTrue(themes.contains("light"), "visual baseline must cover Light theme for \(screenID)")
            XCTAssertTrue(themes.contains("dark"), "visual baseline must cover Dark theme for \(screenID)")
            if coreSystemScreens.contains(screenID) {
                XCTAssertTrue(themes.contains("system"), "core visual baseline must cover System appearance for \(screenID)")
            }
            let expectedViewport = try XCTUnwrap(expectedViewports[screenID])
            XCTAssertEqual((viewport["width"] as? NSNumber)?.intValue, expectedViewport.width)
            XCTAssertEqual((viewport["height"] as? NSNumber)?.intValue, expectedViewport.height)
            XCTAssertEqual(screen["axTargetIdentifier"] as? String, expectedAXTargets[screenID])
            XCTAssertTrue((screen["axFrameAudit"] as? Bool) == true, "visual-only comparison is not enough for \(screenID)")

            for theme in themes {
                let artifact = try XCTUnwrap(artifacts[theme], "missing \(theme) artifact for \(screenID)")
                XCTAssertTrue(artifact.hasSuffix("-\(theme).png"), "artifact should encode theme in filename: \(artifact)")
                XCTAssertFalse(artifact.contains(" "), "artifact paths must stay script-friendly: \(artifact)")
            }
        }

        XCTAssertEqual(tolerances["comparisonMode"] as? String, "semantic")
        XCTAssertEqual(tolerances["allowPixelPerfectOnly"] as? Bool, false)
        XCTAssertGreaterThanOrEqual((tolerances["minimumBytes"] as? NSNumber)?.intValue ?? 0, 30_000)
        XCTAssertGreaterThanOrEqual((tolerances["minimumWidth"] as? NSNumber)?.intValue ?? 0, 640)
        XCTAssertGreaterThanOrEqual((tolerances["minimumHeight"] as? NSNumber)?.intValue ?? 0, 420)
        XCTAssertGreaterThanOrEqual((tolerances["minimumLuminanceRange"] as? NSNumber)?.intValue ?? 0, 12)
        XCTAssertGreaterThanOrEqual((tolerances["minimumColorBuckets"] as? NSNumber)?.intValue ?? 0, 8)
        XCTAssertEqual(tolerances["requiresAXFrameAudit"] as? Bool, true)

        let rasterComparison = try XCTUnwrap(manifest["rasterComparison"] as? [String: Any])
        XCTAssertEqual((rasterComparison["perChannelDeltaThreshold"] as? NSNumber)?.doubleValue, 0.10)
        XCTAssertEqual((rasterComparison["maximumChangedPixelRatio"] as? NSNumber)?.doubleValue, 0.005)
        XCTAssertEqual((rasterComparison["maximumMeanAbsoluteError"] as? NSNumber)?.doubleValue, 0.01)

        let baselineContext = try XCTUnwrap(manifest["baselineContext"] as? [String: Any])
        let evidenceSourceCommit = try runTool([
            "git", "-C", packageRoot().path, "log", "-1", "--format=%H", "--",
            "Sources", "Package.swift", "script/capture_ui_evidence.sh"
        ])
        XCTAssertEqual(evidenceSourceCommit.exitCode, 0, evidenceSourceCommit.output)
        XCTAssertEqual(
            baselineContext["sourceCommit"] as? String,
            evidenceSourceCommit.output.trimmingCharacters(in: .whitespacesAndNewlines)
        )
        XCTAssertEqual(baselineContext["locale"] as? String, "en-US")
        XCTAssertEqual(baselineContext["timeZoneIdentifier"] as? String, "UTC")
        XCTAssertEqual(baselineContext["referenceInstant"] as? String, "2026-07-10T12:00:00Z")
    }

