        XCTAssertTrue(smokeScript.contains("script/kokoro_tts_runtime.py"))
        XCTAssertTrue(smokeScript.contains("SUISUI_LOCAL_VOICE_EVIDENCE_FILE requires SUISUI_KOKORO_EXECUTABLE to be the checked-in reference wrapper script/kokoro_tts_runtime.py"))
        XCTAssertTrue(smokeScript.contains("KOKORO_RUNTIME_WRAPPER_RELATIVE=\"script/kokoro_tts_runtime.py\""))
