    }

    private func writeVisiblePNGWithBlueDelta(
        to url: URL,
        width: Int,
        height: Int,
        mutatedPixelCount: Int,
        blueDelta: UInt8,
        trailingBytes: Int = 0
    ) throws {
        var pixels = [UInt8](repeating: 0, count: width * height * 4)
        let boundedMutationCount = max(0, min(mutatedPixelCount, width * height))
        for y in 0..<height {
            for x in 0..<width {
                let pixelIndex = (y * width) + x
                let offset = pixelIndex * 4
                let lightStripe = ((x / 24) + (y / 24)).isMultiple(of: 2)
                pixels[offset] = lightStripe ? 245 : 32
                pixels[offset + 1] = lightStripe ? 245 : 74
                let originalBlue: UInt8 = lightStripe ? 245 : 128
                pixels[offset + 2] = pixelIndex < boundedMutationCount
                    ? UInt8(max(0, Int(originalBlue) - Int(blueDelta)))
                    : originalBlue
                pixels[offset + 3] = 255
            }
        }

        guard let context = CGContext(
            data: &pixels,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: width * 4,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ), let image = context.makeImage() else {
            XCTFail("Could not create threshold PNG fixture context.")
            return
        }
        guard let destination = CGImageDestinationCreateWithURL(url as CFURL, "public.png" as CFString, 1, nil) else {
            XCTFail("Could not create threshold PNG fixture destination.")
            return
        }
        CGImageDestinationAddImage(destination, image, nil)
        XCTAssertTrue(CGImageDestinationFinalize(destination))

        if trailingBytes > 0 {
            let handle = try FileHandle(forWritingTo: url)
            try handle.seekToEnd()
            try handle.write(contentsOf: Data(repeating: 0, count: trailingBytes))
            try handle.close()
        }
    }

    private func visualBaselineManifestFixture(
        artifacts: [String: String],
        baselineRoot: String,
        requiredVisibleTextLines: [String]? = nil
    ) throws -> String {
        let artifactLines = artifacts
            .sorted { $0.key < $1.key }
            .map { "          \"\($0.key)\": \"\($0.value)\"" }
            .joined(separator: ",\n")
        let themeLines = artifacts.keys
            .sorted()
            .map { "\"\($0)\"" }
            .joined(separator: ", ")
        let visibleTextLines: String
        if let requiredVisibleTextLines {
            let encoded = try requiredVisibleTextLines.map { line in
                let data = try JSONSerialization.data(withJSONObject: line, options: [.fragmentsAllowed])
                return String(decoding: data, as: UTF8.self)
            }.joined(separator: ", ")
            visibleTextLines = "\n              \"requiredVisibleTextLines\": [\(encoded)],"
        } else {
            visibleTextLines = ""
        }

        return """
        {
          "schemaVersion": 2,
          "artifactRoot": "screenshots",
          "baselineRoot": "\(baselineRoot)",
          "baselineContext": {
            "sourceCommit": "fixture-commit",
            "normalRoute": "project-board",
            "locale": "en-US",
            "timeZoneIdentifier": "UTC",
            "referenceInstant": "2026-07-10T12:00:00Z"
          },
          "rasterComparison": {
            "perChannelDeltaThreshold": 0.10,
            "maximumChangedPixelRatio": 0.005,
            "maximumMeanAbsoluteError": 0.01
          },
          "semanticTolerances": {
            "comparisonMode": "semantic",
            "allowPixelPerfectOnly": false,
            "minimumBytes": 50000,
            "minimumWidth": 640,
            "minimumHeight": 420,
            "minimumLuminanceRange": 12,
            "minimumColorBuckets": 2,
            "blackScreenMaximumLuminance": 8,
            "requiresAXFrameAudit": true
          },
          "screens": [
            {
              "id": "project-board",
              "title": "Project Board",
              "themes": [\(themeLines)],
              "viewport": {
                "width": 800,
                "height": 600
              },
              "sourceCommit": "fixture-commit",
              "normalRoute": "project-board",
              "locale": "en-US",
              "appearances": [\(themeLines)],
              "axFrameAudit": true,
              "axTargetIdentifier": "project-board-root",
        \(visibleTextLines)
              "artifacts": {
        \(artifactLines)
              }
            }
          ]
        }
        """
    }

    private func readPackageFile(_ relativePath: String) throws -> String {
        let url = packageRoot().appendingPathComponent(relativePath)
        return try String(contentsOf: url, encoding: .utf8)
    }

    private func accessibilitySourceAnchorCount(in output: String) throws -> Int {
        let pattern = #"OK: accessibility source anchors are present \(([0-9]+) anchors\)"#
        let regex = try NSRegularExpression(pattern: pattern)
        let outputRange = NSRange(output.startIndex..<output.endIndex, in: output)
        let match = try XCTUnwrap(regex.firstMatch(in: output, range: outputRange))
        let countRange = try XCTUnwrap(Range(match.range(at: 1), in: output))
        return try XCTUnwrap(Int(output[countRange]))
    }

    private func removeItemIfPresent(at url: URL) throws {
        guard FileManager.default.fileExists(atPath: url.path) else {
            return
        }
        try FileManager.default.removeItem(at: url)
    }

